const defaultUnits=()=>['Nos','Kg','Mtr','sqft','Ltr','Box','Set'].map((name,i)=>({id:'default-unit-'+i,code:'U'+String(i+1).padStart(3,'0'),name,status:'Active'}));
const normalizeData=data=>({...data,quotations:data.quotations||[],units:data.units||defaultUnits()});
let cloudRevision=0,cloudReady=false,cloudSaving=false,cloudLoading=false,resumeEditor=false;
const cloudStatus=text=>{$('#cloudStatus').textContent=text};
async function api(path,method='GET',data){const response=await fetch('/api/'+path,{method,credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(30000)});let result;try{result=await response.json()}catch{throw Error('Server is starting or unavailable. Wait a moment and retry.')}if(!response.ok)throw Object.assign(Error(result.error||'Request failed'),{status:response.status});return result}
function lockCloud(keepEditor=false){cloudReady=false;resumeEditor=keepEditor&&$('#modal').open;if($('#modal').open)$('#modal').close();if($('#passwordDialog').open)$('#passwordDialog').close();document.body.classList.add('cloud-locked');$('#cloudLogin').hidden=false;$('#loginPassword').value='';cloudStatus('Sign in to access shared records');if(!resumeEditor){db={items:[],suppliers:[],customers:[],units:[],quotations:[],invoices:[]};render()}}
function unlockCloud(){document.body.classList.remove('cloud-locked');$('#cloudLogin').hidden=true;cloudReady=true;$('#loginPassword').value='';$('#legacyNotice').hidden=!legacyData||!Object.values(legacyData).some(rows=>rows.length)}
async function loadCloud(manual=false){if(cloudSaving||cloudLoading)return;cloudLoading=true;try{const snapshot=await api('state');if(cloudReady&&document.querySelector('dialog[open]'))return;db=normalizeData(snapshot.data);cloudRevision=snapshot.revision;unlockCloud();render();cloudStatus('Connected · changes shared across devices');if(manual)toast('Latest shared records loaded')}catch(e){if(e.status===401)lockCloud();else{cloudStatus('Connection unavailable · retry before saving');if(manual)alert(e.message);if(!cloudReady)$('#loginError').textContent=e.message}}finally{cloudLoading=false}}
async function cloudSave(next){if(cloudSaving||cloudLoading){alert('Please wait for the current request to finish.');return false}if(!cloudReady){alert('Sign in before saving.');return false}cloudSaving=true;const controls=[...document.querySelectorAll('button,input,select,textarea')].map(el=>[el,el.disabled]);controls.forEach(([el])=>el.disabled=true);cloudStatus('Saving to shared database…');try{const snapshot=await api('state','PUT',{revision:cloudRevision,data:next});db=normalizeData(snapshot.data);cloudRevision=snapshot.revision;cloudStatus('Saved to shared database · '+new Date().toLocaleTimeString());return true}catch(e){cloudStatus('Not saved · '+e.message);$('#error').textContent=e.message;if(e.status===401){$('#loginError').textContent='Your session expired. Sign in to continue your edit.';lockCloud(true)}else alert(e.message);return false}finally{cloudSaving=false;controls.forEach(([el,disabled])=>el.disabled=disabled)}}
function canonical(v){if(Array.isArray(v))return '['+v.map(canonical).join(',')+']';if(v&&typeof v==='object')return '{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}';return JSON.stringify(v)}
function mergeBackup(current,incoming){const next={},counts=[];for(const key of ['items','suppliers','customers','units','quotations','invoices']){const rows=incoming[key]||[];if(!Array.isArray(rows))throw Error('Invalid backup');next[key]=[...current[key]];let count=0;for(const r of rows){if(!r||typeof r.id!=='string')throw Error('Invalid backup record');const existing=next[key].find(x=>x.id===r.id);if(existing){if(canonical(existing)!==canonical(r))throw Error('Import stopped: a '+key+' record differs from the shared version. Review the backup before importing; no records were changed.');continue}next[key].push(r);count++}counts.push(key+': '+count)}return {next,counts}}
async function importCloudBackup(data){if(!cloudReady)throw Error('Sign in first');if(data.version!==1||!Array.isArray(data.items)||!Array.isArray(data.invoices))throw Error('Choose a JSON backup downloaded from this ERP.');await loadCloud();if(!cloudReady)throw Error('Could not connect');const {next,counts}=mergeBackup(db,data);if(!confirm('Import these additional records into the shared database?\n'+counts.join('\n')+'\nExisting records will not be replaced.'))return;if(await persist(next)){render();toast('Records imported to shared database')}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('#loginError').textContent='Signing in…';try{await api('login','POST',{password:$('#loginPassword').value});$('#loginError').textContent='';if(resumeEditor){unlockCloud();$('#modal').showModal();resumeEditor=false;cloudStatus('Signed in · retry saving your edit')}else await loadCloud()}catch(error){$('#loginError').textContent=error.message}finally{button.disabled=false}};
$('#logoutCloud').onclick=async()=>{if(cloudSaving)return;if(!confirm('Sign out of this device?'))return;try{await api('logout','POST',{});lockCloud()}catch(e){alert('Could not sign out. '+e.message)}};
$('#refreshCloud').onclick=()=>loadCloud(true);
$('#importLocal').onclick=async()=>{try{await importCloudBackup({version:1,...legacyData})}catch(e){alert(e.message)}};
$('#exportLocal').onclick=()=>download('RAM-ERP-device-backup.json',JSON.stringify({version:1,...legacyData},null,2),'application/json');
$('#changePassword').onclick=()=>{$('#passwordForm').reset();$('#passwordError').textContent='';$('#passwordDialog').showModal()};$('#cancelPassword').onclick=()=>$('#passwordDialog').close();
$('#passwordForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('password','POST',{current:$('#currentPassword').value,password:$('#newPassword').value});$('#passwordForm').reset();lockCloud();$('#loginError').textContent='Password changed. Sign in with your new password.'}catch(e){$('#passwordError').textContent=e.message}finally{button.disabled=false}};
setInterval(()=>{if(cloudReady&&!cloudSaving&&!document.hidden&&!document.querySelector('dialog[open]'))loadCloud()},15000);
window.addEventListener('focus',()=>{if(cloudReady&&!document.querySelector('dialog[open]'))loadCloud()});
window.addEventListener('beforeunload',e=>{if(cloudSaving){e.preventDefault();e.returnValue=''}});
loadCloud();
